#include <atomic>
#include <iostream>
#include <thread>

int main() {
    std::atomic<int> ready{0};
    std::jthread worker([&] {
        ready.store(42);
        std::atomic_notify_one(&ready);
        std::atomic_notify_all(&ready);
    });
    std::atomic_wait(&ready, 0);
    std::atomic_wait_explicit(&ready, 0, std::memory_order_seq_cst);
    worker.join();
    std::cout << ready.load() << "\n";
}
